{
  "name": "whatsapp-cloud-api",
  "version": "1.0.0",
  "description": "WhatsApp Cloud API integration with Express and TypeScript",
  "main": "dist/index.js",
  "scripts": {
    "dev": "ts-node-dev --respawn src/index.ts",
    "build": "tsc",
    "start": "node dist/index.js"
  },
  "dependencies": {
    "axios": "^1.7.0",
    "dotenv": "^16.4.0",
    "express": "^4.21.0"
  },
  "devDependencies": {
    "@types/express": "^5.0.0",
    "@types/node": "^22.0.0",
    "ts-node-dev": "^2.0.0",
    "typescript": "^5.6.0"
  }
}

import express from 'express';
import dotenv from 'dotenv';
import { WhatsAppClient } from './whatsapp-client';
import { TemplateManager } from './template-manager';
import {
  validateHMAC,
  rawBodyMiddleware,
  handleWebhookVerification,
  parseWebhookPayload,
  extractMessageContent,
} from './webhook-handler';
import { WhatsAppConfig, IncomingMessage, StatusUpdate } from './types';

dotenv.config();

// === Configuration ===

const config: WhatsAppConfig = {
  token: process.env.WHATSAPP_TOKEN!,
  phoneNumberId: process.env.PHONE_NUMBER_ID!,
  wabaId: process.env.WABA_ID!,
  appSecret: process.env.APP_SECRET!,
  verifyToken: process.env.VERIFY_TOKEN!,
};

const whatsapp = new WhatsAppClient(config);
const templates = new TemplateManager(config);

// === Express Setup ===

const app = express();
app.disable('x-powered-by');
const PORT = process.env.PORT || 3000;

// Raw body capture MUST come before express.json()
app.use(express.json({ verify: rawBodyMiddleware }));

// === Webhook Routes ===

// GET - Webhook verification (Meta sends challenge)
app.get('/webhook', handleWebhookVerification(config.verifyToken));

// POST - Receive messages and status updates
app.post('/webhook', validateHMAC(config.appSecret), async (req, res) => {
  // Respond 200 immediately (WhatsApp requires response within 5 seconds)
  res.sendStatus(200);

  try {
    const { messages, statuses } = parseWebhookPayload(req.body);

    for (const message of messages) {
      await handleIncomingMessage(message);
    }

    for (const status of statuses) {
      handleStatusUpdate(status);
    }
  } catch (error) {
    console.error('Error processing webhook:', error);
  }
});

// === Message Handler ===

async function handleIncomingMessage(message: IncomingMessage): Promise<void> {
  const from = message.from;
  const content = extractMessageContent(message);

  console.log(`Message from ${from}: [${content.type}] ${content.text || content.buttonId || ''}`);

  // Mark as read
  await whatsapp.markAsRead(message.id);

  // TODO: Implement your message handling logic here
  // Example: Echo back the message
  switch (content.type) {
    case 'text':
      await whatsapp.sendText(from, `Recebi sua mensagem: "${content.text}"`);
      break;

    case 'button':
      await whatsapp.sendText(from, `Voce selecionou: ${content.text}`);
      break;

    case 'list':
      await whatsapp.sendText(from, `Voce escolheu: ${content.text}`);
      break;

    case 'image':
    case 'document':
    case 'video':
    case 'audio':
      await whatsapp.sendText(from, `Recebi sua midia (${content.type}).`);
      break;

    default:
      await whatsapp.sendText(from, 'Desculpe, nao entendi. Como posso ajudar?');
      break;
  }
}

// === Status Handler ===

function handleStatusUpdate(status: StatusUpdate): void {
  console.log(`Status update: ${status.id} -> ${status.status}`);

  if (status.status === 'failed') {
    console.error(`Message delivery failed:`, status.errors);
  }
}

// === Health Check ===

app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// === Start Server ===

app.listen(PORT, () => {
  console.log(`WhatsApp webhook server running on port ${PORT}`);
  console.log(`Webhook URL: http://localhost:${PORT}/webhook`);
  console.log(`Health check: http://localhost:${PORT}/health`);
});

export { whatsapp, templates };

import axios, { AxiosInstance } from 'axios';
import { WhatsAppConfig, TemplateInfo } from './types';

export class TemplateManager {
  private client: AxiosInstance;
  private wabaId: string;

  constructor(config: WhatsAppConfig) {
    const version = config.graphApiVersion || 'v21.0';
    this.wabaId = config.wabaId;

    this.client = axios.create({
      baseURL: `https://graph.facebook.com/${version}`,
      headers: {
        Authorization: `Bearer ${config.token}`,
        'Content-Type': 'application/json',
      },
    });
  }

  async listTemplates(status?: string): Promise<TemplateInfo[]> {
    const params: Record<string, any> = { limit: 100 };
    if (status) params.status = status;

    const response = await this.client.get(`/${this.wabaId}/message_templates`, { params });
    return response.data.data;
  }

  async createTemplate(
    name: string,
    category: 'MARKETING' | 'UTILITY' | 'AUTHENTICATION',
    language: string,
    components: Array<{
      type: 'HEADER' | 'BODY' | 'FOOTER' | 'BUTTONS';
      format?: string;
      text?: string;
      example?: Record<string, any>;
      buttons?: Array<Record<string, any>>;
    }>
  ): Promise<{ id: string; status: string; category: string }> {
    const response = await this.client.post(`/${this.wabaId}/message_templates`, {
      name,
      category,
      language,
      components,
    });
    return response.data;
  }

  async deleteTemplate(templateName: string): Promise<void> {
    await this.client.delete(`/${this.wabaId}/message_templates`, {
      data: { name: templateName },
    });
  }

  async getApprovedTemplates(): Promise<TemplateInfo[]> {
    return this.listTemplates('APPROVED');
  }

  async getPendingTemplates(): Promise<TemplateInfo[]> {
    return this.listTemplates('PENDING');
  }

  async getRejectedTemplates(): Promise<TemplateInfo[]> {
    return this.listTemplates('REJECTED');
  }
}

// WhatsApp Cloud API TypeScript Types

// === Configuration ===

export interface WhatsAppConfig {
  token: string;
  phoneNumberId: string;
  wabaId: string;
  appSecret: string;
  verifyToken: string;
  graphApiVersion?: string;
}

// === Outgoing Messages ===

export interface SendMessagePayload {
  messaging_product: 'whatsapp';
  recipient_type?: 'individual';
  to: string;
  type: MessageType;
  text?: { preview_url?: boolean; body: string };
  template?: TemplatePayload;
  image?: MediaPayload;
  document?: DocumentPayload;
  video?: MediaPayload;
  audio?: MediaPayload;
  location?: LocationPayload;
  contacts?: ContactPayload[];
  interactive?: InteractivePayload;
  reaction?: ReactionPayload;
  context?: { message_id: string };
}

export type MessageType =
  | 'text' | 'template' | 'image' | 'document' | 'video'
  | 'audio' | 'location' | 'contacts' | 'interactive'
  | 'reaction' | 'sticker';

export interface TemplatePayload {
  name: string;
  language: { code: string };
  components?: TemplateComponent[];
}

export interface TemplateComponent {
  type: 'header' | 'body' | 'button';
  sub_type?: 'url' | 'quick_reply';
  index?: number;
  parameters?: TemplateParameter[];
}

export interface TemplateParameter {
  type: 'text' | 'image' | 'document' | 'video';
  text?: string;
  image?: { link: string };
  document?: { link: string; filename?: string };
  video?: { link: string };
}

export interface MediaPayload {
  id?: string;
  link?: string;
  caption?: string;
}

export interface DocumentPayload extends MediaPayload {
  filename?: string;
}

export interface LocationPayload {
  longitude: number;
  latitude: number;
  name?: string;
  address?: string;
}

export interface ContactPayload {
  name: { formatted_name: string; first_name?: string; last_name?: string };
  phones?: Array<{ phone: string; type?: string }>;
  emails?: Array<{ email: string; type?: string }>;
}

export interface InteractivePayload {
  type: 'button' | 'list' | 'product' | 'product_list' | 'flow';
  header?: { type: 'text' | 'image' | 'video' | 'document'; text?: string };
  body: { text: string };
  footer?: { text: string };
  action: InteractiveAction;
}

export interface InteractiveAction {
  buttons?: Array<{
    type: 'reply';
    reply: { id: string; title: string };
  }>;
  button?: string;
  sections?: Array<{
    title: string;
    rows: Array<{ id: string; title: string; description?: string }>;
  }>;
  catalog_id?: string;
  product_retailer_id?: string;
  name?: string;
  parameters?: Record<string, any>;
}

export interface ReactionPayload {
  message_id: string;
  emoji: string;
}

// === API Responses ===

export interface SendMessageResponse {
  messaging_product: string;
  contacts: Array<{ input: string; wa_id: string }>;
  messages: Array<{ id: string }>;
}

// === Webhook Events ===

export interface WebhookPayload {
  object: string;
  entry: WebhookEntry[];
}

export interface WebhookEntry {
  id: string;
  changes: WebhookChange[];
}

export interface WebhookChange {
  value: WebhookValue;
  field: string;
}

export interface WebhookValue {
  messaging_product: string;
  metadata: { display_phone_number: string; phone_number_id: string };
  contacts?: Array<{ profile: { name: string }; wa_id: string }>;
  messages?: IncomingMessage[];
  statuses?: StatusUpdate[];
  errors?: WebhookError[];
}

export interface IncomingMessage {
  from: string;
  id: string;
  timestamp: string;
  type: string;
  text?: { body: string };
  image?: { id: string; mime_type: string; sha256: string; caption?: string };
  document?: { id: string; mime_type: string; filename: string; caption?: string };
  video?: { id: string; mime_type: string; caption?: string };
  audio?: { id: string; mime_type: string };
  location?: { latitude: number; longitude: number; name?: string; address?: string };
  contacts?: ContactPayload[];
  interactive?: {
    type: 'button_reply' | 'list_reply' | 'nfm_reply';
    button_reply?: { id: string; title: string };
    list_reply?: { id: string; title: string; description?: string };
    nfm_reply?: { response_json: string };
  };
  reaction?: { message_id: string; emoji: string };
  context?: { from: string; id: string };
  referral?: {
    source_url: string;
    source_type: string;
    source_id: string;
    headline?: string;
    body?: string;
    ctwa_clid?: string;
  };
}

export interface StatusUpdate {
  id: string;
  status: 'sent' | 'delivered' | 'read' | 'failed';
  timestamp: string;
  recipient_id: string;
  conversation?: {
    id: string;
    origin: { type: string };
    expiration_timestamp?: string;
  };
  pricing?: {
    billable: boolean;
    pricing_model: string;
    category: string;
  };
  errors?: Array<{ code: number; title: string; message: string }>;
}

export interface WebhookError {
  code: number;
  title: string;
  message: string;
  error_data?: { details: string };
}

// === Template Management ===

export interface TemplateInfo {
  name: string;
  status: 'APPROVED' | 'PENDING' | 'REJECTED' | 'PAUSED' | 'DISABLED';
  category: 'MARKETING' | 'UTILITY' | 'AUTHENTICATION';
  language: string;
  components: Array<{
    type: string;
    format?: string;
    text?: string;
    buttons?: Array<{ type: string; text: string; url?: string }>;
  }>;
  id: string;
  rejected_reason?: string;
}

import crypto from 'crypto';
import { Request, Response, NextFunction } from 'express';
import { WebhookPayload, IncomingMessage, StatusUpdate } from './types';

const SAFE_CHALLENGE_RE = /^[A-Za-z0-9._-]{1,200}$/;
const SIGNATURE_RE = /^sha256=[a-f0-9]{64}$/i;

/**
 * Middleware para validar assinatura HMAC-SHA256 dos webhooks do WhatsApp.
 *
 * A Meta assina cada request com o App Secret. Validar esta assinatura
 * previne que requests falsificados sejam processados. Usar comparacao
 * constant-time previne timing attacks.
 *
 * IMPORTANTE: Este middleware deve ser aplicado ANTES de qualquer body parser
 * que altere o raw body (express.json() por exemplo).
 */
export function validateHMAC(appSecret: string) {
  return (req: Request, res: Response, next: NextFunction): void => {
    const signature = req.headers['x-hub-signature-256'] as string;

    if (!signature) {
      console.warn('Webhook request without signature header');
      res.sendStatus(401);
      return;
    }

    const rawBody = (req as any).rawBody;
    if (!rawBody) {
      console.error('Raw body not available. Ensure rawBody middleware is configured.');
      res.sendStatus(500);
      return;
    }

    const expectedSignature =
      'sha256=' +
      crypto.createHmac('sha256', appSecret).update(rawBody).digest('hex');

    if (!SIGNATURE_RE.test(signature)) {
      console.warn('Invalid webhook signature format');
      res.sendStatus(401);
      return;
    }

    const signatureBuffer = Buffer.from(signature, 'utf8');
    const expectedSignatureBuffer = Buffer.from(expectedSignature, 'utf8');
    const isValid =
      signatureBuffer.length === expectedSignatureBuffer.length &&
      crypto.timingSafeEqual(signatureBuffer, expectedSignatureBuffer);

    if (!isValid) {
      console.warn('Invalid webhook signature');
      res.sendStatus(401);
      return;
    }

    next();
  };
}

/**
 * Middleware para capturar o raw body antes do JSON parse.
 * Necessario para validacao HMAC.
 */
export function rawBodyMiddleware(req: Request, _res: Response, buf: Buffer): void {
  (req as any).rawBody = buf;
}

/**
 * Handler de verificacao do webhook (GET).
 * A Meta envia um challenge que deve ser retornado para confirmar o endpoint.
 */
export function handleWebhookVerification(verifyToken: string) {
  return (req: Request, res: Response): void => {
    const mode = req.query['hub.mode'] as string;
    const token = req.query['hub.verify_token'] as string;
    const challenge = req.query['hub.challenge'] as string;

    if (mode === 'subscribe' && token === verifyToken && SAFE_CHALLENGE_RE.test(challenge)) {
      console.log('Webhook verified successfully');
      res.type('text/plain').status(200).send(challenge);
    } else {
      console.warn('Webhook verification failed: invalid token');
      res.status(mode === 'subscribe' && token === verifyToken ? 400 : 403).send();
    }
  };
}

/**
 * Extrai mensagens e status updates do payload do webhook.
 */
export function parseWebhookPayload(payload: WebhookPayload): {
  messages: IncomingMessage[];
  statuses: StatusUpdate[];
} {
  const messages: IncomingMessage[] = [];
  const statuses: StatusUpdate[] = [];

  for (const entry of payload.entry || []) {
    for (const change of entry.changes || []) {
      if (change.value.messages) {
        messages.push(...change.value.messages);
      }
      if (change.value.statuses) {
        statuses.push(...change.value.statuses);
      }
    }
  }

  return { messages, statuses };
}

/**
 * Extrai o texto ou ID de selecao de uma mensagem recebida.
 */
export function extractMessageContent(message: IncomingMessage): {
  type: string;
  text?: string;
  buttonId?: string;
  listId?: string;
  mediaId?: string;
  location?: { latitude: number; longitude: number };
  reaction?: { emoji: string; messageId: string };
} {
  switch (message.type) {
    case 'text':
      return { type: 'text', text: message.text?.body };

    case 'interactive':
      if (message.interactive?.type === 'button_reply') {
        return {
          type: 'button',
          buttonId: message.interactive.button_reply?.id,
          text: message.interactive.button_reply?.title,
        };
      }
      if (message.interactive?.type === 'list_reply') {
        return {
          type: 'list',
          listId: message.interactive.list_reply?.id,
          text: message.interactive.list_reply?.title,
        };
      }
      if (message.interactive?.type === 'nfm_reply') {
        return {
          type: 'flow',
          text: message.interactive.nfm_reply?.response_json,
        };
      }
      return { type: 'interactive' };

    case 'image':
      return { type: 'image', mediaId: message.image?.id };

    case 'document':
      return { type: 'document', mediaId: message.document?.id };

    case 'video':
      return { type: 'video', mediaId: message.video?.id };

    case 'audio':
      return { type: 'audio', mediaId: message.audio?.id };

    case 'location':
      return {
        type: 'location',
        location: message.location
          ? { latitude: message.location.latitude, longitude: message.location.longitude }
          : undefined,
      };

    case 'reaction':
      return {
        type: 'reaction',
        reaction: message.reaction
          ? { emoji: message.reaction.emoji, messageId: message.reaction.message_id }
          : undefined,
      };

    default:
      return { type: message.type };
  }
}

import axios, { AxiosInstance } from 'axios';
import { WhatsAppConfig, SendMessagePayload, SendMessageResponse } from './types';

export class WhatsAppClient {
  private client: AxiosInstance;
  private phoneNumberId: string;
  private wabaId: string;

  constructor(config: WhatsAppConfig) {
    const version = config.graphApiVersion || 'v21.0';
    this.phoneNumberId = config.phoneNumberId;
    this.wabaId = config.wabaId;

    this.client = axios.create({
      baseURL: `https://graph.facebook.com/${version}`,
      headers: {
        Authorization: `Bearer ${config.token}`,
        'Content-Type': 'application/json',
      },
    });
  }

  async sendMessage(payload: SendMessagePayload): Promise<SendMessageResponse> {
    return this.sendWithRetry(payload);
  }

  async sendText(to: string, body: string, previewUrl = false): Promise<SendMessageResponse> {
    return this.sendMessage({
      messaging_product: 'whatsapp',
      to,
      type: 'text',
      text: { body, preview_url: previewUrl },
    });
  }

  async sendTemplate(
    to: string,
    templateName: string,
    languageCode: string,
    components?: SendMessagePayload['template']
  ): Promise<SendMessageResponse> {
    return this.sendMessage({
      messaging_product: 'whatsapp',
      to,
      type: 'template',
      template: {
        name: templateName,
        language: { code: languageCode },
        ...components,
      },
    });
  }

  async sendImage(to: string, imageUrl: string, caption?: string): Promise<SendMessageResponse> {
    return this.sendMessage({
      messaging_product: 'whatsapp',
      to,
      type: 'image',
      image: { link: imageUrl, caption },
    });
  }

  async sendDocument(
    to: string,
    documentUrl: string,
    filename: string,
    caption?: string
  ): Promise<SendMessageResponse> {
    return this.sendMessage({
      messaging_product: 'whatsapp',
      to,
      type: 'document',
      document: { link: documentUrl, filename, caption },
    });
  }

  async sendInteractiveButtons(
    to: string,
    bodyText: string,
    buttons: Array<{ id: string; title: string }>,
    headerText?: string,
    footerText?: string
  ): Promise<SendMessageResponse> {
    return this.sendMessage({
      messaging_product: 'whatsapp',
      to,
      type: 'interactive',
      interactive: {
        type: 'button',
        ...(headerText && { header: { type: 'text', text: headerText } }),
        body: { text: bodyText },
        ...(footerText && { footer: { text: footerText } }),
        action: {
          buttons: buttons.map((b) => ({
            type: 'reply' as const,
            reply: { id: b.id, title: b.title },
          })),
        },
      },
    });
  }

  async sendInteractiveList(
    to: string,
    bodyText: string,
    buttonText: string,
    sections: Array<{
      title: string;
      rows: Array<{ id: string; title: string; description?: string }>;
    }>,
    headerText?: string,
    footerText?: string
  ): Promise<SendMessageResponse> {
    return this.sendMessage({
      messaging_product: 'whatsapp',
      to,
      type: 'interactive',
      interactive: {
        type: 'list',
        ...(headerText && { header: { type: 'text', text: headerText } }),
        body: { text: bodyText },
        ...(footerText && { footer: { text: footerText } }),
        action: { button: buttonText, sections },
      },
    });
  }

  async sendReaction(to: string, messageId: string, emoji: string): Promise<SendMessageResponse> {
    return this.sendMessage({
      messaging_product: 'whatsapp',
      to,
      type: 'reaction',
      reaction: { message_id: messageId, emoji },
    });
  }

  async sendLocation(
    to: string,
    latitude: number,
    longitude: number,
    name?: string,
    address?: string
  ): Promise<SendMessageResponse> {
    return this.sendMessage({
      messaging_product: 'whatsapp',
      to,
      type: 'location',
      location: { latitude, longitude, name, address },
    });
  }

  async markAsRead(messageId: string): Promise<void> {
    await this.client.post(`/${this.phoneNumberId}/messages`, {
      messaging_product: 'whatsapp',
      status: 'read',
      message_id: messageId,
    });
  }

  private async sendWithRetry(
    payload: SendMessagePayload,
    maxRetries = 3
  ): Promise<SendMessageResponse> {
    const nonRetryableCodes = [100, 131026, 131051, 132000, 132001, 132005, 133010];

    for (let attempt = 1; attempt <= maxRetries; attempt++) {
      try {
        const response = await this.client.post<SendMessageResponse>(
          `/${this.phoneNumberId}/messages`,
          payload
        );
        return response.data;
      } catch (error: any) {
        const errorCode = error.response?.data?.error?.code;
        const errorMessage = error.response?.data?.error?.message || error.message;

        if (nonRetryableCodes.includes(errorCode)) {
          throw new Error(`WhatsApp API Error ${errorCode}: ${errorMessage}`);
        }

        if (attempt < maxRetries) {
          const delay = Math.pow(2, attempt) * 1000;
          await new Promise((resolve) => setTimeout(resolve, delay));
          continue;
        }

        throw new Error(`WhatsApp API Error after ${maxRetries} retries: ${errorMessage}`);
      }
    }

    throw new Error('Unexpected: retry loop exited without return or throw');
  }
}

"""WhatsApp Webhook Handler with HMAC-SHA256 validation."""

import hashlib
import hmac
import os
import re
from functools import wraps
from typing import Any

from flask import Response, abort, request


_SAFE_CHALLENGE_RE = re.compile(r"^[A-Za-z0-9._-]{1,200}$")


def validate_hmac_signature(app_secret: str | None = None):
    """
    Flask decorator to validate HMAC-SHA256 signature on webhook requests.

    A Meta assina cada request com o App Secret no header X-Hub-Signature-256.
    Validar esta assinatura previne requests falsificados.
    Usa hmac.compare_digest para comparacao constant-time (previne timing attacks).
    """
    secret = app_secret or os.environ["APP_SECRET"]

    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            signature = request.headers.get("X-Hub-Signature-256", "")
            if not signature:
                abort(401, "Missing signature header")

            raw_body = request.get_data()
            expected = "sha256=" + hmac.new(
                secret.encode(), raw_body, hashlib.sha256
            ).hexdigest()

            if not hmac.compare_digest(signature, expected):
                abort(401, "Invalid signature")

            return f(*args, **kwargs)

        return decorated_function

    return decorator


def verify_webhook(verify_token: str | None = None):
    """
    Handle webhook verification (GET request from Meta).
    Returns the challenge to confirm the webhook endpoint.
    """
    token = verify_token or os.environ["VERIFY_TOKEN"]

    mode = request.args.get("hub.mode")
    req_token = request.args.get("hub.verify_token")
    challenge = request.args.get("hub.challenge")

    if mode != "subscribe" or req_token != token:
        abort(403, "Verification failed")

    if not challenge or not _SAFE_CHALLENGE_RE.fullmatch(challenge):
        abort(400, "Invalid challenge")

    return Response(challenge, status=200, mimetype="text/plain")


def parse_webhook_payload(data: dict[str, Any]) -> dict[str, list]:
    """
    Parse webhook payload and extract messages and status updates.

    Returns dict with 'messages' and 'statuses' lists.
    """
    messages: list[dict] = []
    statuses: list[dict] = []

    for entry in data.get("entry", []):
        for change in entry.get("changes", []):
            value = change.get("value", {})
            if "messages" in value:
                messages.extend(value["messages"])
            if "statuses" in value:
                statuses.extend(value["statuses"])

    return {"messages": messages, "statuses": statuses}


def extract_message_content(message: dict[str, Any]) -> dict[str, Any]:
    """
    Extract readable content from an incoming message.

    Returns dict with 'type' and relevant fields (text, button_id, media_id, etc.).
    """
    msg_type = message.get("type", "unknown")

    if msg_type == "text":
        return {"type": "text", "text": message.get("text", {}).get("body")}

    if msg_type == "interactive":
        interactive = message.get("interactive", {})
        int_type = interactive.get("type")

        if int_type == "button_reply":
            reply = interactive.get("button_reply", {})
            return {"type": "button", "button_id": reply.get("id"), "text": reply.get("title")}

        if int_type == "list_reply":
            reply = interactive.get("list_reply", {})
            return {"type": "list", "list_id": reply.get("id"), "text": reply.get("title")}

        if int_type == "nfm_reply":
            return {
                "type": "flow",
                "text": interactive.get("nfm_reply", {}).get("response_json"),
            }

        return {"type": "interactive"}

    if msg_type in ("image", "document", "video", "audio"):
        media_data = message.get(msg_type, {})
        return {"type": msg_type, "media_id": media_data.get("id")}

    if msg_type == "location":
        loc = message.get("location", {})
        return {
            "type": "location",
            "latitude": loc.get("latitude"),
            "longitude": loc.get("longitude"),
        }

    if msg_type == "reaction":
        reaction = message.get("reaction", {})
        return {
            "type": "reaction",
            "emoji": reaction.get("emoji"),
            "message_id": reaction.get("message_id"),
        }

    return {"type": msg_type}

"""WhatsApp Cloud API Client with async support and retry logic."""

import os
import asyncio
from typing import Any

import httpx

GRAPH_API = "https://graph.facebook.com/v21.0"


class WhatsAppClient:
    """Client for WhatsApp Cloud API with retry and error handling."""

    def __init__(
        self,
        token: str | None = None,
        phone_number_id: str | None = None,
        waba_id: str | None = None,
    ):
        self.token = token or os.environ["WHATSAPP_TOKEN"]
        self.phone_number_id = phone_number_id or os.environ["PHONE_NUMBER_ID"]
        self.waba_id = waba_id or os.environ["WABA_ID"]
        self.headers = {
            "Authorization": f"Bearer {self.token}",
            "Content-Type": "application/json",
        }

    async def send_message(self, payload: dict[str, Any]) -> dict:
        """Send a message with retry logic."""
        return await self._send_with_retry(payload)

    async def send_text(self, to: str, body: str, preview_url: bool = False) -> dict:
        """Send a text message."""
        return await self.send_message({
            "messaging_product": "whatsapp",
            "to": to,
            "type": "text",
            "text": {"body": body, "preview_url": preview_url},
        })

    async def send_template(
        self,
        to: str,
        template_name: str,
        language_code: str,
        components: list[dict] | None = None,
    ) -> dict:
        """Send a template message."""
        payload: dict[str, Any] = {
            "messaging_product": "whatsapp",
            "to": to,
            "type": "template",
            "template": {
                "name": template_name,
                "language": {"code": language_code},
            },
        }
        if components:
            payload["template"]["components"] = components
        return await self.send_message(payload)

    async def send_image(self, to: str, image_url: str, caption: str | None = None) -> dict:
        """Send an image message."""
        return await self.send_message({
            "messaging_product": "whatsapp",
            "to": to,
            "type": "image",
            "image": {"link": image_url, **({"caption": caption} if caption else {})},
        })

    async def send_document(
        self, to: str, document_url: str, filename: str, caption: str | None = None
    ) -> dict:
        """Send a document message."""
        return await self.send_message({
            "messaging_product": "whatsapp",
            "to": to,
            "type": "document",
            "document": {
                "link": document_url,
                "filename": filename,
                **({"caption": caption} if caption else {}),
            },
        })

    async def send_interactive_buttons(
        self,
        to: str,
        body_text: str,
        buttons: list[dict[str, str]],
        header_text: str | None = None,
        footer_text: str | None = None,
    ) -> dict:
        """Send interactive button message (max 3 buttons)."""
        interactive: dict[str, Any] = {
            "type": "button",
            "body": {"text": body_text},
            "action": {
                "buttons": [
                    {"type": "reply", "reply": {"id": b["id"], "title": b["title"]}}
                    for b in buttons
                ]
            },
        }
        if header_text:
            interactive["header"] = {"type": "text", "text": header_text}
        if footer_text:
            interactive["footer"] = {"text": footer_text}

        return await self.send_message({
            "messaging_product": "whatsapp",
            "to": to,
            "type": "interactive",
            "interactive": interactive,
        })

    async def send_interactive_list(
        self,
        to: str,
        body_text: str,
        button_text: str,
        sections: list[dict],
        header_text: str | None = None,
        footer_text: str | None = None,
    ) -> dict:
        """Send interactive list message (max 10 options across sections)."""
        interactive: dict[str, Any] = {
            "type": "list",
            "body": {"text": body_text},
            "action": {"button": button_text, "sections": sections},
        }
        if header_text:
            interactive["header"] = {"type": "text", "text": header_text}
        if footer_text:
            interactive["footer"] = {"text": footer_text}

        return await self.send_message({
            "messaging_product": "whatsapp",
            "to": to,
            "type": "interactive",
            "interactive": interactive,
        })

    async def send_reaction(self, to: str, message_id: str, emoji: str) -> dict:
        """React to a message with an emoji."""
        return await self.send_message({
            "messaging_product": "whatsapp",
            "to": to,
            "type": "reaction",
            "reaction": {"message_id": message_id, "emoji": emoji},
        })

    async def send_location(
        self,
        to: str,
        latitude: float,
        longitude: float,
        name: str | None = None,
        address: str | None = None,
    ) -> dict:
        """Send a location message."""
        return await self.send_message({
            "messaging_product": "whatsapp",
            "to": to,
            "type": "location",
            "location": {
                "latitude": latitude,
                "longitude": longitude,
                **({"name": name} if name else {}),
                **({"address": address} if address else {}),
            },
        })

    async def mark_as_read(self, message_id: str) -> None:
        """Mark a message as read (blue checkmarks)."""
        async with httpx.AsyncClient() as client:
            await client.post(
                f"{GRAPH_API}/{self.phone_number_id}/messages",
                json={
                    "messaging_product": "whatsapp",
                    "status": "read",
                    "message_id": message_id,
                },
                headers=self.headers,
            )

    async def _send_with_retry(self, payload: dict, max_retries: int = 3) -> dict:
        """Send message with exponential backoff retry."""
        non_retryable_codes = {100, 131026, 131051, 132000, 132001, 132005, 133010}

        for attempt in range(1, max_retries + 1):
            try:
                async with httpx.AsyncClient() as client:
                    response = await client.post(
                        f"{GRAPH_API}/{self.phone_number_id}/messages",
                        json=payload,
                        headers=self.headers,
                    )
                    response.raise_for_status()
                    return response.json()
            except httpx.HTTPStatusError as e:
                error_data = e.response.json().get("error", {})
                error_code = error_data.get("code", 0)
                error_message = error_data.get("message", str(e))

                if error_code in non_retryable_codes:
                    raise RuntimeError(f"WhatsApp API Error {error_code}: {error_message}")

                if attempt < max_retries:
                    delay = 2**attempt
                    await asyncio.sleep(delay)
                    continue

                raise RuntimeError(
                    f"WhatsApp API Error after {max_retries} retries: {error_message}"
                )

        raise RuntimeError("Unexpected: retry loop exited without return or raise")

